import {MockupRenderer} from './renderer.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const defaults=()=>({fit:'cover',zoom:1,panX:0,panY:0,screenBrightness:100,screenContrast:100,screenSaturation:100,screenTemperature:0,sceneBrightness:100,sceneContrast:100,sceneSaturation:100,sceneTemperature:0,reflection:1,bodyAmount:0,bodyColor:'#a4b2c0'});
let catalog=[],current=null,state=null,renderer,images=null,loadSerial=0,busy=false,comparing=false,frame=0,filter='Todos';const states=new Map(),cache=new Map(),userImages=new Map();
function toast(message,error=false){$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function remember(){if(!current)return;states.set(current.id,state);try{localStorage.setItem('insany-studio-v1',JSON.stringify(Object.fromEntries([...states].map(([id,v])=>[id,{...v,artAspect:undefined}]))))}catch{/* Session remains fully usable if browser storage is full. */}}
function render(){if(!renderer||!images||!state)return;try{const settings=comparing?{...defaults(),artAspect:current.aspect}:state;renderer.draw(settings,768,1024)}catch(e){toast(e.message,true)}}
function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(render);if(current)quality();remember()}
function slider(parent,key,label,min,max,step=1,format=v=>String(v)){
 const el=document.createElement('label');el.className='slider';el.innerHTML=`<span class="slider-line"><span>${label}</span><output for="${key}"></output></span><input type="range" id="${key}" min="${min}" max="${max}" step="${step}" aria-label="${label}">`;
 const input=el.querySelector('input'),output=el.querySelector('output');el.update=()=>{const v=state?.[key]??defaults()[key];input.value=v;output.textContent=format(Number(v));input.style.setProperty('--progress',((v-min)/(max-min)*100)+'%')};input.addEventListener('input',()=>{state[key]=Number(input.value);el.update();schedule()});input.addEventListener('dblclick',()=>{state[key]=defaults()[key];el.update();schedule()});$(parent).append(el);return el;
}
const percent=v=>`${v}%`,signed=v=>`${v>0?'+':''}${Math.round(v)}`;
slider('#crop-controls','zoom','Zoom',1,3,.01,v=>v.toFixed(2)+'×');slider('#crop-controls','panX','Posição horizontal',-1,1,.01,v=>signed(v*100));slider('#crop-controls','panY','Posição vertical',-1,1,.01,v=>signed(v*100));
for(const [parent,prefix] of [['#screen-controls','screen'],['#scene-controls','scene']]){slider(parent,prefix+'Brightness','Brilho',0,200,1,percent);slider(parent,prefix+'Contrast','Contraste',0,200,1,percent);slider(parent,prefix+'Saturation','Saturação',0,200,1,percent);slider(parent,prefix+'Temperature','Temperatura',-100,100,1,signed)}
slider('#scene-controls','reflection','Reflexo do vidro',0,2,.01,v=>percent(Math.round(v*100)));slider('#body-controls','bodyAmount','Intensidade da cor',0,100,1,percent);
function updateControls(){$$('.slider').forEach(x=>x.update());$$('#fit button').forEach(x=>x.classList.toggle('active',x.dataset.fit===state.fit));$('#body-color').value=state.bodyColor;const upload=userImages.get(current.id);$('#file-info').hidden=!upload;$('#file-info').textContent=upload?`${upload.name} · ${upload.image.width} × ${upload.image.height} px`:'';quality()}
function quality(){const art=userImages.get(current.id)?.image;if(!art){$('#quality').hidden=true;return}const q=current.quad.map(([x,y])=>[x*current.width,y*current.height]);const w=Math.max(Math.hypot(q[1][0]-q[0][0],q[1][1]-q[0][1]),Math.hypot(q[2][0]-q[3][0],q[2][1]-q[3][1]));const h=Math.max(Math.hypot(q[3][0]-q[0][0],q[3][1]-q[0][1]),Math.hypot(q[2][0]-q[1][0],q[2][1]-q[1][1]));const low=art.width<w*state.zoom||art.height<h*state.zoom;$('#quality').hidden=!low;$('#quality').textContent='A arte tem menos pixels que a área da tela. O arquivo sai no tamanho nativo, mas a arte pode perder nitidez.'}
function gallery(){$('#gallery').replaceChildren();for(const m of catalog.filter(m=>filter==='Todos'||m.family===filter)){const b=document.createElement('button');b.className='model'+(current?.id===m.id?' selected':'');b.dataset.id=m.id;b.setAttribute('aria-pressed',String(current?.id===m.id));b.setAttribute('aria-label',`${m.family} ${m.id}, ${m.name}`);b.innerHTML=`<span class="model-visual"><img src="${m.asset}/thumb.png${m.assetVersion?'?v='+encodeURIComponent(m.assetVersion):''}" alt="${m.family} em ${m.name.toLowerCase()}" loading="lazy"><span class="model-number">${m.id}</span></span><span class="model-name">${m.name}</span>`;b.onclick=()=>selectModel(m);$('#gallery').append(b)}$('#count').textContent=catalog.filter(m=>filter==='Todos'||m.family===filter).length}
async function image(url){const img=new Image();img.decoding='async';img.src=url;await img.decode();return img}
const layerFiles=['base.png','art.png','mask.png','glass.png','foreground.png','body-mask.png'];
async function loadLayers(asset,files=layerFiles,version){const suffix=version?'?v='+encodeURIComponent(version):'';return Promise.all(files.map(n=>image(`${asset}/${n}${suffix}`)))}
async function getImages(m){if(cache.has(m.id))return cache.get(m.id);const arr=await loadLayers(m.previewAsset||m.asset,m.previewAsset?layerFiles:(m.layerFiles||layerFiles),m.assetVersion);cache.set(m.id,arr);if(cache.size>3){const oldest=cache.keys().next().value;if(oldest!==m.id)cache.delete(oldest)}return arr}
async function selectModel(m){if(busy)return;remember();const serial=++loadSerial;busy=true;$('#loading').hidden=false;$('#export').disabled=true;try{const loaded=await getImages(m);if(serial!==loadSerial)return;current=m;state=states.get(m.id)||defaults();state.artAspect=userImages.get(m.id)?.image.width/userImages.get(m.id)?.image.height||m.aspect;states.set(m.id,state);images=[...loaded];if(userImages.has(m.id))images[1]=userImages.get(m.id).image;renderer.setModel(m,images);$('#model-title').textContent=`${m.family.toUpperCase()} ${m.id} / ${m.name.toUpperCase()}`;$('#resolution').textContent=`${m.width} × ${m.height} px`;$('#export-size').textContent=`${m.width} × ${m.height} px`;gallery();updateControls();render();$('#export').disabled=false}catch(e){toast('Não foi possível abrir o modelo. '+e.message,true)}finally{busy=false;$('#loading').hidden=true}}
async function upload(file){if(!file||busy||!current)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Escolha uma imagem PNG, JPG ou WebP.',true);return}if(file.size>40*1024*1024){toast('A imagem deve ter até 40 MB.',true);return}busy=true;$('#export').disabled=true;$('#loading').hidden=false;const url=URL.createObjectURL(file);try{const img=await image(url);if(img.width>renderer.maxSize||img.height>renderer.maxSize)throw Error(`O limite desta placa gráfica é ${renderer.maxSize} px por lado. Reduza a imagem enviada.`);renderer.setTexture(1,img);userImages.set(current.id,{image:img,name:file.name});images[1]=img;state.artAspect=img.width/img.height;state.zoom=1;state.panX=0;state.panY=0;updateControls();schedule();toast('Sua imagem já está na tela.')}catch(e){toast('Não foi possível usar a imagem. '+e.message,true)}finally{URL.revokeObjectURL(url);busy=false;$('#export').disabled=false;$('#loading').hidden=true;$('#file').value=''}}
$('#file').onchange=e=>upload(e.target.files[0]);let dragDepth=0;window.addEventListener('dragover',e=>{e.preventDefault()});window.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('#canvas-area').classList.remove('drag');upload(e.dataTransfer.files[0])});window.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){dragDepth++;$('#canvas-area').classList.add('drag')}});window.addEventListener('dragleave',()=>{if(--dragDepth<=0)$('#canvas-area').classList.remove('drag')});
$$('.tabs button').forEach(b=>b.onclick=()=>{filter=b.dataset.family;$$('.tabs button').forEach(x=>x.classList.toggle('active',x===b));gallery()});$$('#fit button').forEach(b=>b.onclick=()=>{if(!state)return;state.fit=b.dataset.fit;updateControls();schedule()});$('#body-color').oninput=e=>{if(!state)return;state.bodyColor=e.target.value;if(state.bodyAmount===0)state.bodyAmount=50;updateControls();schedule()};$$('.swatches button').forEach(b=>b.onclick=()=>{$('#body-color').value=b.dataset.color;$('#body-color').dispatchEvent(new Event('input'))});
$('#reset').onclick=async()=>{if(!current||busy)return;const id=current.id;userImages.delete(id);state=defaults();states.set(id,state);await selectModel(current);toast('Ajustes e tela original restaurados.')};
function compare(on){if(!images||busy)return;comparing=on;renderer.setTexture(1,on?cache.get(current.id)[1]:images[1]);render()}
$('#compare').onpointerdown=e=>{e.currentTarget.setPointerCapture(e.pointerId);compare(true)};$('#compare').onpointerup=()=>compare(false);$('#compare').onpointercancel=()=>compare(false);$('#compare').onkeydown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();compare(true)}};$('#compare').onkeyup=()=>compare(false);$('#compare').onblur=()=>compare(false);
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.stage').requestFullscreen()}catch{toast('A ampliação não está disponível neste navegador.',true)}};
$('#export').onclick=async()=>{if(!current||busy)return;busy=true;const button=$('#export'),original=button.innerHTML;button.disabled=true;button.textContent='Exportando…';const model=current,settings={...state};let nativeLayers=null;try{await new Promise(requestAnimationFrame);if(model.previewAsset){nativeLayers=await loadLayers(model.asset,model.layerFiles||layerFiles,model.assetVersion);const exportLayers=[...nativeLayers];if(userImages.has(model.id))exportLayers[1]=userImages.get(model.id).image;renderer.setModel(model,exportLayers)}renderer.draw(settings,model.width,model.height);const format=$('#format').value,mime=format==='png'?'image/png':'image/jpeg';const blob=await new Promise(resolve=>renderer.canvas.toBlob(resolve,mime,.98));if(!blob)throw Error('O navegador não conseguiu criar o arquivo.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Insany_${model.family}_${model.id}_${model.width}x${model.height}.${format==='png'?'png':'jpg'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(`Exportado em ${model.width} × ${model.height} px.`)}catch(e){toast(e.message,true)}finally{try{if(model.previewAsset)renderer.setModel(model,images)}finally{if(nativeLayers)for(const img of nativeLayers)img.src='';busy=false;button.disabled=false;button.innerHTML=original;render()}}};
window.addEventListener('render-error',e=>toast(e.detail,true));window.addEventListener('error',e=>console.error('Studio:',e.message));
try{const saved=JSON.parse(localStorage.getItem('insany-studio-v1')||'{}');for(const [id,s]of Object.entries(saved)){const d=defaults();for(const [k,v]of Object.entries(d)){if(typeof s[k]===typeof v)d[k]=s[k]}if(!/^#[0-9a-f]{6}$/i.test(d.bodyColor))d.bodyColor='#a4b2c0';states.set(id,d)}}catch{/* Ignore unsupported or corrupt storage. */}
try{renderer=new MockupRenderer($('#preview'));const response=await fetch('assets/catalog.json',{cache:'no-cache'});if(!response.ok)throw Error('Catálogo indisponível.');catalog=await response.json();gallery();await selectModel(catalog[0]);}catch(e){$('#loading').hidden=true;toast(e.message,true)}
